SELECT
    transit_job_id,
    internal_id,
    country_id,
    start_place,
    end_place,
    start_mileage,
    end_mileage,
    driver_name,
    driver_id,
    driver_company,
    DATETIME(start_date, cmt.country_timezone) as start_date,
    DATETIME(end_date, cmt.country_timezone) as end_date,
    DATETIME(created_at, cmt.country_timezone) as created_at,
    created_by_id,
    created_by_name,
    DATETIME(updated_at, cmt.country_timezone) as updated_at,
    updated_by_id,
    updated_by_name,
    DATETIME(deleted_at, cmt.country_timezone) as deleted_at,
    deleted_by_id,
    deleted_by_name, 
    DATETIME(checkin_at, cmt.country_timezone) as checkin_at,
    checkin_by_id,
    checkin_by_name, 
    DATETIME(checkin_at, cmt.country_timezone) as checkout_at,
    checkout_by_id,
    checkout_by_name, 
    transit_type,
    transit_job_status,
    transit_job_comment,
    pending_cars
FROM `{{params.project_name}}.staging.CarTransitJobs`
INNER JOIN `{{params.project_name}}.staging.CountryMetadata` cmt using (country_id)
where updated_at >= '{{params.start_ts}}' and updated_at < '{{params.end_ts}}'